import numpy as np
from PIL import Image
im = np.array(Image.open('first_frame.png').convert('RGB')).astype(int)
# scan rows: classify liquid juice pixels (R in 120..210, G 70..130, B 30..90, R-G>30, G-B>20)
def isj(c):
    r,g,b=c
    return r>120 and g>60 and b<100 and r-g>25 and g-b>18
for y in range(78,134,2):
    xs=[x for x in range(95,140) if isj(im[y,x])]
    if xs: print(y, min(xs), max(xs), len(xs))
    else: print(y,'-')
EOF"
